	INCLUDE "common.i"
	FILLBANK 5
	FILLBANK 2
	FILLBANK 4
	FILLBANK 50
	FILLBANK 9
	FILLBANK 10
	FILLBANK 11
	FILLBANK 12
	FILLBANK 13
	MMU 7, 60
	ORG $E000
	DUP 512
	DB low($ * 5)
	EDUP
	ORG $8000
start:	jr start
	SAVENEX OPEN "v13_320.nex", start, $BFF0, 5
	SAVENEX CFG 1, $4000, 1, 1
	SAVENEX CFG3 1, 1, $6000, 128
	SAVENEX BAR 1, 7, 0, 0, 200
	SAVENEX PALETTE MEM 60, 0
	SAVENEX SCREEN L2_320
	SAVENEX COPPER 60, 512
	SAVENEX BANK 5, 2, 4, 50
	SAVENEX CLOSE "common.i"
